<script setup lang="ts">
import { Plus, RefreshCw, ShoppingBag } from "@lucide/vue";
import type { PaginatedResponse, PurchaseSummary } from "~~/types";
usePageTitle("Pembelian");
const page = ref(1);
const { data, status, refresh } = await useAsyncData("purchases", () => $fetch<PaginatedResponse<PurchaseSummary>>("/api/purchases", { query: { page: page.value, pageSize: 10 } }), { watch: [page] });
const purchases = computed(() => data.value?.data ?? []);
const formatMoney = (value: number) => new Intl.NumberFormat("id-ID", { style: "currency", currency: "IDR", maximumFractionDigits: 0 }).format(value);
</script>
<template><div><section class="flex items-end justify-between pt-8 pb-7"><div><p class="text-[11px] font-semibold uppercase tracking-[.14em] text-brand">Transaksi</p><h2 class="mt-2 font-display text-3xl font-bold">Pembelian</h2><p class="mt-2 text-sm text-muted">Kelola penerimaan barang dan stok masuk.</p></div><NuxtLink to="/admin/transactions/purchases/create"><BaseButton><Plus class="h-4 w-4" /> Pembelian Baru</BaseButton></NuxtLink></section><section class="overflow-hidden rounded-4xl border border-line/70 bg-surface shadow-card"><div class="flex justify-end border-b border-line/70 p-4"><BaseButton variant="secondary" :disabled="status === 'pending'" @click="refresh"><RefreshCw class="h-4 w-4" /> Muat ulang</BaseButton></div><div v-if="status === 'pending'" class="p-12 text-center text-muted">Memuat data…</div><div v-else-if="!purchases.length" class="flex flex-col items-center gap-3 p-16 text-muted"><ShoppingBag class="h-10 w-10" /><p>Belum ada pembelian.</p></div><div v-else class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="bg-night/5 text-xs uppercase text-muted"><tr><th class="px-5 py-4">Nomor</th><th class="px-5 py-4">Supplier</th><th class="px-5 py-4">Tanggal</th><th class="px-5 py-4">Status</th><th class="px-5 py-4 text-right">Total</th></tr></thead><tbody><tr v-for="item in purchases" :key="item.id" class="border-t border-line/60"><td class="px-5 py-4 font-semibold"><NuxtLink class="text-brand hover:underline" :to="`/admin/transactions/purchases/${item.id}`">{{ item.number }}</NuxtLink></td><td class="px-5 py-4">{{ item.supplier.name }}</td><td class="px-5 py-4">{{ new Date(item.date).toLocaleDateString('id-ID') }}</td><td class="px-5 py-4"><BaseBadge>{{ item.status }}</BaseBadge></td><td class="px-5 py-4 text-right font-semibold">{{ formatMoney(item.total) }}</td></tr></tbody></table></div></section></div></template>
